private static int GetEventIndex(string eventType)
{
    switch (eventType?.ToLowerInvariant())
    {
        case "blue": return 0;
        case "green": return 1;
        case "orange": return 2;
        case "purple": return 3;
        case "red": return 4;
        default: return -1;
    }
}

private static Sprite GetSpriteSafe(Sprite[] list, int index, string fieldName, string eventType)
{
    if (list == null || index &lt; 0 || index &gt;= list.Length)
    {
        Debug.LogWarning($"[{nameof(CollectAndWinManager)}] {fieldName} not configured for '{eventType}'.");
        return null;
    }
    return list[index];
}

